
#[cfg(test)]mod greater75_massslow76_request_development_tests {
 use super::*;const OTHER:u32=0x71234567;
 fn world()->World{let mut w=super::super::native_login::LoginController::default().snapshot().world.clone();let f:serde_json::Value=serde_json::from_slice(include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\LiTo381-Modern\tests\fixtures\native-world-current.json")).unwrap();for key in ["world","start","status","actor","bot"]{let h=f["packets"][key].as_str().unwrap();w.accept(&(0..h.len()).step_by(2).map(|i|u8::from_str_radix(&h[i..i+2],16).unwrap()).collect::<Vec<_>>()).unwrap();}w.learned_skills.clear();w.learned_skills.extend([75,76]);w.mp=Some([1,100]);w.hp=Some([1,100]);let mut a=w.own_actor().unwrap().clone();a.id=OTHER;a.incarnation+=10;a.x+=1;w.actors.insert(OTHER,a);w}
 #[test]fn greater_corpse_id_and_massslow_actor_xy_have_distinct_exact_envelopes(){let mut w=world();let before=serde_json::to_value(&w).unwrap();let a=&w.actors[&OTHER];let mut slow=vec![20,9,3];slow.extend(OTHER.to_le_bytes());slow.extend(a.x.to_le_bytes());slow.extend(a.y.to_le_bytes());assert_eq!(request(&w,76,Some(OTHER)).unwrap(),slow);assert_eq!(slow.len(),11);assert_eq!(serde_json::to_value(&w).unwrap(),before);w.actors.get_mut(&OTHER).unwrap().dead=true;let before=serde_json::to_value(&w).unwrap();let mut greater=vec![20,9,2];greater.extend(OTHER.to_le_bytes());assert_eq!(request(&w,75,Some(OTHER)).unwrap(),greater);assert_eq!(greater.len(),7);assert_eq!(serde_json::to_value(&w).unwrap(),before);assert_eq!((reuse_millis(75),reuse_millis(76)),(10,3000));}
 #[test]fn wrong_life_self_or_missing_target_cannot_be_reinterpreted(){let mut w=world();assert!(request(&w,75,Some(OTHER)).is_err());w.actors.get_mut(&OTHER).unwrap().dead=true;assert!(request(&w,76,Some(OTHER)).is_err());for id in [75,76]{assert!(request(&w,id,None).is_err());assert!(request(&w,id,Some(w.own_actor().unwrap().id)).is_err());assert!(request(&w,id,Some(0xf1234567)).is_err());}}
 #[test]fn formal_screen_range_and_book_MP_gates_do_not_predict_full_cost(){for id in [75,76]{let mut w=world();let a=w.own_actor().unwrap().clone();w.actors.get_mut(&OTHER).unwrap().dead=id==75;w.actors.get_mut(&OTHER).unwrap().x=a.x+if id==75{18}else{10};assert!(request(&w,id,Some(OTHER)).is_ok());w.actors.get_mut(&OTHER).unwrap().x=a.x+if id==75{20}else{11};assert!(request(&w,id,Some(OTHER)).is_err());w.actors.get_mut(&OTHER).unwrap().x=a.x+1;w.learned_skills.remove(&id);assert!(request(&w,id,Some(OTHER)).is_err());w.learned_skills.insert(id);w.mp=Some([0,100]);assert!(request(&w,id,Some(OTHER)).is_err());}}
 #[test]fn captured_corpse_and_live_selection_do_not_cross_life_revision_or_menu(){use super::super::native_skill_selection::{Model,Target};let mut w=world();let mut m=Model::default();m.sync(7,&w,true);m.select(Some(76)).unwrap();let live=Target::capture(&w,OTHER).unwrap();assert!(m.choice(7,&w,Some(live)).is_ok());w.actors.get_mut(&OTHER).unwrap().dead=true;m.select(Some(75)).unwrap();assert!(m.choice(7,&w,Some(live)).is_err());let dead=Target::capture(&w,OTHER).unwrap();assert!(m.choice(7,&w,Some(dead)).is_ok());w.actors.get_mut(&OTHER).unwrap().action_sequence+=1;assert!(m.choice(7,&w,Some(dead)).is_err());}
}
